-- Additive migration: preserve legacy tables and all user foreign keys.
CREATE TABLE dataset_runs (
 run_id TEXT PRIMARY KEY, dataset TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('running','completed','expired')),
 data_date TEXT NOT NULL, expected_rows INTEGER NOT NULL, expected_chunks INTEGER NOT NULL,
 payload_hash TEXT NOT NULL, meta_json TEXT NOT NULL, started_at TEXT NOT NULL, source_time TEXT NOT NULL, completed_at TEXT
);
CREATE INDEX dataset_runs_status ON dataset_runs(dataset,status,started_at);
CREATE TABLE dataset_chunks (
 run_id TEXT NOT NULL REFERENCES dataset_runs(run_id), chunk_index INTEGER NOT NULL,
 payload_hash TEXT NOT NULL,row_count INTEGER NOT NULL,PRIMARY KEY(run_id,chunk_index)
);
CREATE TABLE dataset_items (run_id TEXT NOT NULL REFERENCES dataset_runs(run_id),item_key TEXT NOT NULL,PRIMARY KEY(run_id,item_key));
CREATE TABLE dataset_active (dataset TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES dataset_runs(run_id),data_date TEXT NOT NULL,started_at TEXT NOT NULL,source_time TEXT NOT NULL);
CREATE TABLE live_quotes (
 code TEXT NOT NULL,instrument_type TEXT NOT NULL,name TEXT,close REAL NOT NULL,pct_change REAL NOT NULL,
 quote_date TEXT NOT NULL,quote_time TEXT NOT NULL,quote_source TEXT NOT NULL,updated_at TEXT NOT NULL,
 PRIMARY KEY(code,instrument_type)
);
CREATE TABLE stock_snapshot AS SELECT CAST(NULL AS TEXT) AS _run_id,t.* FROM stock_latest t WHERE 0;
CREATE UNIQUE INDEX stock_snapshot_identity ON stock_snapshot(_run_id,code);
CREATE VIEW stock_current_base AS SELECT t.code,t.name,t.trade_date,t.close,t.score_total,t.data_completeness,t.updated_at,t.instrument_type,t.quote_date,t.quote_time,t.quote_source,t.is_st,t.quote_updated_at,t.quote_pct_change FROM stock_snapshot t JOIN dataset_active a ON a.run_id=t._run_id AND a.dataset='screener' UNION ALL SELECT t.code,t.name,t.trade_date,t.close,t.score_total,t.data_completeness,t.updated_at,t.instrument_type,t.quote_date,t.quote_time,t.quote_source,t.is_st,t.quote_updated_at,t.quote_pct_change FROM stock_latest t WHERE NOT EXISTS (SELECT 1 FROM dataset_active WHERE dataset='screener');
CREATE VIEW stock_current AS SELECT b.code,CASE WHEN q.quote_date || 'T' || q.quote_time >= COALESCE(b.quote_date,b.trade_date) || 'T' || COALESCE(b.quote_time,'00:00:00') THEN COALESCE(q.name,b.name) ELSE b.name END AS name,b.trade_date,CASE WHEN q.quote_date || 'T' || q.quote_time >= COALESCE(b.quote_date,b.trade_date) || 'T' || COALESCE(b.quote_time,'00:00:00') THEN COALESCE(q.close,b.close) ELSE b.close END AS close,b.score_total,b.data_completeness,b.updated_at,b.instrument_type,CASE WHEN q.quote_date || 'T' || q.quote_time >= COALESCE(b.quote_date,b.trade_date) || 'T' || COALESCE(b.quote_time,'00:00:00') THEN COALESCE(q.quote_date,b.quote_date) ELSE b.quote_date END AS quote_date,CASE WHEN q.quote_date || 'T' || q.quote_time >= COALESCE(b.quote_date,b.trade_date) || 'T' || COALESCE(b.quote_time,'00:00:00') THEN COALESCE(q.quote_time,b.quote_time) ELSE b.quote_time END AS quote_time,CASE WHEN q.quote_date || 'T' || q.quote_time >= COALESCE(b.quote_date,b.trade_date) || 'T' || COALESCE(b.quote_time,'00:00:00') THEN COALESCE(q.quote_source,b.quote_source) ELSE b.quote_source END AS quote_source,b.is_st,CASE WHEN q.quote_date || 'T' || q.quote_time >= COALESCE(b.quote_date,b.trade_date) || 'T' || COALESCE(b.quote_time,'00:00:00') THEN COALESCE(q.updated_at,b.quote_updated_at) ELSE b.quote_updated_at END AS quote_updated_at,CASE WHEN q.quote_date || 'T' || q.quote_time >= COALESCE(b.quote_date,b.trade_date) || 'T' || COALESCE(b.quote_time,'00:00:00') THEN COALESCE(q.pct_change,b.quote_pct_change) ELSE b.quote_pct_change END AS quote_pct_change FROM stock_current_base b LEFT JOIN live_quotes q ON q.code=b.code AND q.instrument_type=b.instrument_type;
CREATE TABLE screen_snapshot AS SELECT CAST(NULL AS TEXT) AS _run_id,t.* FROM stock_screen_latest t WHERE 0;
CREATE UNIQUE INDEX screen_snapshot_identity ON screen_snapshot(_run_id,code);
CREATE VIEW stock_screen_current AS SELECT t.code,t.trade_date,t.market,t.industry,t.pct_change,t.turnover_rate,t.ret_5d,t.ret_20d,t.ret_60d,t.ma20_slope,t.volume_ratio_20,t.volatility_20,t.updated_at,t.volume_ratio_5,t.amount,t.amount_ratio_5,t.amount_ratio_20,t.rsi_14,t.ret_120d,t.ret_250d,t.distance_high_20,t.distance_high_60,t.distance_high_250,t.distance_low_250,t.price_percentile_250,t.volatility_60,t.max_drawdown_60,t.score_trend,t.score_momentum,t.score_volume_price,t.score_risk FROM screen_snapshot t JOIN dataset_active a ON a.run_id=t._run_id AND a.dataset='screener' UNION ALL SELECT t.code,t.trade_date,t.market,t.industry,t.pct_change,t.turnover_rate,t.ret_5d,t.ret_20d,t.ret_60d,t.ma20_slope,t.volume_ratio_20,t.volatility_20,t.updated_at,t.volume_ratio_5,t.amount,t.amount_ratio_5,t.amount_ratio_20,t.rsi_14,t.ret_120d,t.ret_250d,t.distance_high_20,t.distance_high_60,t.distance_high_250,t.distance_low_250,t.price_percentile_250,t.volatility_60,t.max_drawdown_60,t.score_trend,t.score_momentum,t.score_volume_price,t.score_risk FROM stock_screen_latest t WHERE NOT EXISTS (SELECT 1 FROM dataset_active WHERE dataset='screener');
CREATE TABLE index_snapshot AS SELECT CAST(NULL AS TEXT) AS _run_id,t.* FROM market_index_latest t WHERE 0;
CREATE UNIQUE INDEX index_snapshot_identity ON index_snapshot(_run_id,code);
CREATE VIEW market_index_current_base AS SELECT t.code,t.name,t.trade_date,t.close,t.pct_change,t.ret_20d,t.ma20_slope,t.volatility_20,t.updated_at,t.quote_date,t.quote_time,t.quote_source,t.quote_updated_at FROM index_snapshot t JOIN dataset_active a ON a.run_id=t._run_id AND a.dataset='screener' UNION ALL SELECT t.code,t.name,t.trade_date,t.close,t.pct_change,t.ret_20d,t.ma20_slope,t.volatility_20,t.updated_at,t.quote_date,t.quote_time,t.quote_source,t.quote_updated_at FROM market_index_latest t WHERE NOT EXISTS (SELECT 1 FROM dataset_active WHERE dataset='screener');
CREATE VIEW market_index_current AS SELECT b.code,CASE WHEN q.quote_date || 'T' || q.quote_time >= COALESCE(b.quote_date,b.trade_date) || 'T' || COALESCE(b.quote_time,'00:00:00') THEN COALESCE(q.name,b.name) ELSE b.name END AS name,b.trade_date,CASE WHEN q.quote_date || 'T' || q.quote_time >= COALESCE(b.quote_date,b.trade_date) || 'T' || COALESCE(b.quote_time,'00:00:00') THEN COALESCE(q.close,b.close) ELSE b.close END AS close,CASE WHEN q.quote_date || 'T' || q.quote_time >= COALESCE(b.quote_date,b.trade_date) || 'T' || COALESCE(b.quote_time,'00:00:00') THEN COALESCE(q.pct_change,b.pct_change) ELSE b.pct_change END AS pct_change,b.ret_20d,b.ma20_slope,b.volatility_20,b.updated_at,CASE WHEN q.quote_date || 'T' || q.quote_time >= COALESCE(b.quote_date,b.trade_date) || 'T' || COALESCE(b.quote_time,'00:00:00') THEN COALESCE(q.quote_date,b.quote_date) ELSE b.quote_date END AS quote_date,CASE WHEN q.quote_date || 'T' || q.quote_time >= COALESCE(b.quote_date,b.trade_date) || 'T' || COALESCE(b.quote_time,'00:00:00') THEN COALESCE(q.quote_time,b.quote_time) ELSE b.quote_time END AS quote_time,CASE WHEN q.quote_date || 'T' || q.quote_time >= COALESCE(b.quote_date,b.trade_date) || 'T' || COALESCE(b.quote_time,'00:00:00') THEN COALESCE(q.quote_source,b.quote_source) ELSE b.quote_source END AS quote_source,CASE WHEN q.quote_date || 'T' || q.quote_time >= COALESCE(b.quote_date,b.trade_date) || 'T' || COALESCE(b.quote_time,'00:00:00') THEN COALESCE(q.updated_at,b.quote_updated_at) ELSE b.quote_updated_at END AS quote_updated_at FROM market_index_current_base b LEFT JOIN live_quotes q ON q.code=b.code AND q.instrument_type='index';
CREATE TABLE fund_snapshot AS SELECT CAST(NULL AS TEXT) AS _run_id,t.* FROM stock_money_flow_latest t WHERE 0;
CREATE UNIQUE INDEX fund_snapshot_identity ON fund_snapshot(_run_id,code);
CREATE VIEW stock_money_flow_current AS SELECT t.code,t.data_date,t.source,t.main_net_inflow,t.main_net_inflow_pct,t.super_large_net_inflow,t.large_net_inflow,t.medium_net_inflow,t.small_net_inflow,t.main_net_inflow_3d,t.main_net_inflow_5d,t.main_net_inflow_10d,t.updated_at FROM fund_snapshot t JOIN dataset_active a ON a.run_id=t._run_id AND a.dataset='fund-flow' UNION ALL SELECT t.code,t.data_date,t.source,t.main_net_inflow,t.main_net_inflow_pct,t.super_large_net_inflow,t.large_net_inflow,t.medium_net_inflow,t.small_net_inflow,t.main_net_inflow_3d,t.main_net_inflow_5d,t.main_net_inflow_10d,t.updated_at FROM stock_money_flow_latest t WHERE NOT EXISTS (SELECT 1 FROM dataset_active WHERE dataset='fund-flow');
CREATE TABLE valuation_snapshot AS SELECT CAST(NULL AS TEXT) AS _run_id,t.* FROM stock_valuation_latest t WHERE 0;
CREATE UNIQUE INDEX valuation_snapshot_identity ON valuation_snapshot(_run_id,code);
CREATE VIEW stock_valuation_current AS SELECT t.code,t.data_date,t.source,t.pe_ttm,t.pb,t.total_market_cap,t.float_market_cap,t.updated_at FROM valuation_snapshot t JOIN dataset_active a ON a.run_id=t._run_id AND a.dataset='valuation' UNION ALL SELECT t.code,t.data_date,t.source,t.pe_ttm,t.pb,t.total_market_cap,t.float_market_cap,t.updated_at FROM stock_valuation_latest t WHERE NOT EXISTS (SELECT 1 FROM dataset_active WHERE dataset='valuation');
CREATE TABLE financial_snapshot AS SELECT CAST(NULL AS TEXT) AS _run_id,t.* FROM stock_financial_latest t WHERE 0;
CREATE UNIQUE INDEX financial_snapshot_identity ON financial_snapshot(_run_id,code);
CREATE VIEW stock_financial_current AS SELECT t.code,t.report_date,t.announcement_date,t.source,t.roe,t.revenue_yoy,t.profit_yoy,t.gross_margin,t.debt_ratio,t.revenue,t.net_profit,t.updated_at FROM financial_snapshot t JOIN dataset_active a ON a.run_id=t._run_id AND a.dataset='financials' UNION ALL SELECT t.code,t.report_date,t.announcement_date,t.source,t.roe,t.revenue_yoy,t.profit_yoy,t.gross_margin,t.debt_ratio,t.revenue,t.net_profit,t.updated_at FROM stock_financial_latest t WHERE NOT EXISTS (SELECT 1 FROM dataset_active WHERE dataset='financials');
CREATE TABLE industry_snapshot AS SELECT CAST(NULL AS TEXT) AS _run_id,t.* FROM stock_industry_latest t WHERE 0;
CREATE UNIQUE INDEX industry_snapshot_identity ON industry_snapshot(_run_id,code);
CREATE VIEW stock_industry_current AS SELECT t.code,t.industry,t.source,t.updated_at FROM industry_snapshot t JOIN dataset_active a ON a.run_id=t._run_id AND a.dataset='industry-map' UNION ALL SELECT t.code,t.industry,t.source,t.updated_at FROM stock_industry_latest t WHERE NOT EXISTS (SELECT 1 FROM dataset_active WHERE dataset='industry-map');
CREATE TABLE sector_snapshot AS SELECT CAST(NULL AS TEXT) AS _run_id,t.* FROM industry_fund_flow_latest t WHERE 0;
CREATE UNIQUE INDEX sector_snapshot_identity ON sector_snapshot(_run_id,industry);
CREATE VIEW industry_fund_flow_current AS SELECT t.industry,t.data_date,t.source,t.inflow_amount,t.outflow_amount,t.net_inflow,t.company_count,t.pct_change,t.updated_at FROM sector_snapshot t JOIN dataset_active a ON a.run_id=t._run_id AND a.dataset='industry-fund-flow' UNION ALL SELECT t.industry,t.data_date,t.source,t.inflow_amount,t.outflow_amount,t.net_inflow,t.company_count,t.pct_change,t.updated_at FROM industry_fund_flow_latest t WHERE NOT EXISTS (SELECT 1 FROM dataset_active WHERE dataset='industry-fund-flow');
CREATE VIEW stock_search_base AS SELECT code,name,trade_date,close,score_total,data_completeness,updated_at,instrument_type,quote_date,quote_time,quote_source,is_st,quote_updated_at,quote_pct_change FROM (
 SELECT code,name,trade_date,close,score_total,data_completeness,updated_at,instrument_type,quote_date,quote_time,quote_source,is_st,quote_updated_at,quote_pct_change,ROW_NUMBER() OVER (PARTITION BY code ORDER BY trade_date DESC,updated_at DESC) AS choice FROM (
 SELECT * FROM stock_current UNION ALL SELECT t.code,t.name,t.trade_date,t.close,t.score_total,t.data_completeness,t.updated_at,t.instrument_type,t.quote_date,t.quote_time,t.quote_source,t.is_st,t.quote_updated_at,t.quote_pct_change FROM stock_snapshot t JOIN dataset_runs r ON r.run_id=t._run_id
 WHERE r.dataset='screener' AND r.status='completed' AND json_extract(r.meta_json,'$.runKind') IN ('supplemental_st','single_stock')
 )) WHERE choice=1;
CREATE VIEW stock_screen_search_current AS SELECT code,trade_date,market,industry,pct_change,turnover_rate,ret_5d,ret_20d,ret_60d,ma20_slope,volume_ratio_20,volatility_20,updated_at,volume_ratio_5,amount,amount_ratio_5,amount_ratio_20,rsi_14,ret_120d,ret_250d,distance_high_20,distance_high_60,distance_high_250,distance_low_250,price_percentile_250,volatility_60,max_drawdown_60,score_trend,score_momentum,score_volume_price,score_risk FROM (
 SELECT code,trade_date,market,industry,pct_change,turnover_rate,ret_5d,ret_20d,ret_60d,ma20_slope,volume_ratio_20,volatility_20,updated_at,volume_ratio_5,amount,amount_ratio_5,amount_ratio_20,rsi_14,ret_120d,ret_250d,distance_high_20,distance_high_60,distance_high_250,distance_low_250,price_percentile_250,volatility_60,max_drawdown_60,score_trend,score_momentum,score_volume_price,score_risk,ROW_NUMBER() OVER (PARTITION BY code ORDER BY trade_date DESC,updated_at DESC) AS choice FROM (
 SELECT * FROM stock_screen_current UNION ALL SELECT t.code,t.trade_date,t.market,t.industry,t.pct_change,t.turnover_rate,t.ret_5d,t.ret_20d,t.ret_60d,t.ma20_slope,t.volume_ratio_20,t.volatility_20,t.updated_at,t.volume_ratio_5,t.amount,t.amount_ratio_5,t.amount_ratio_20,t.rsi_14,t.ret_120d,t.ret_250d,t.distance_high_20,t.distance_high_60,t.distance_high_250,t.distance_low_250,t.price_percentile_250,t.volatility_60,t.max_drawdown_60,t.score_trend,t.score_momentum,t.score_volume_price,t.score_risk FROM screen_snapshot t JOIN dataset_runs r ON r.run_id=t._run_id
 WHERE r.dataset='screener' AND r.status='completed' AND json_extract(r.meta_json,'$.runKind') IN ('supplemental_st','single_stock')
 )) WHERE choice=1;
CREATE INDEX stock_snapshot_score ON stock_snapshot(_run_id,is_st,score_total DESC,code);
CREATE INDEX screen_snapshot_market ON screen_snapshot(_run_id,market,industry);
UPDATE data_refresh_runs SET status='failed',error_message='Expired during refresh coordination migration',completed_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id IN (SELECT id FROM (SELECT id,ROW_NUMBER() OVER (ORDER BY requested_at DESC,id) AS rank FROM data_refresh_runs WHERE status IN ('queued','running')) WHERE rank>1);
CREATE UNIQUE INDEX one_active_refresh ON data_refresh_runs((1)) WHERE status IN ('queued','running');
CREATE VIEW stock_search_current AS SELECT b.code,CASE WHEN q.quote_date || 'T' || q.quote_time >= COALESCE(b.quote_date,b.trade_date) || 'T' || COALESCE(b.quote_time,'00:00:00') THEN COALESCE(q.name,b.name) ELSE b.name END AS name,b.trade_date,CASE WHEN q.quote_date || 'T' || q.quote_time >= COALESCE(b.quote_date,b.trade_date) || 'T' || COALESCE(b.quote_time,'00:00:00') THEN COALESCE(q.close,b.close) ELSE b.close END AS close,b.score_total,b.data_completeness,b.updated_at,b.instrument_type,CASE WHEN q.quote_date || 'T' || q.quote_time >= COALESCE(b.quote_date,b.trade_date) || 'T' || COALESCE(b.quote_time,'00:00:00') THEN COALESCE(q.quote_date,b.quote_date) ELSE b.quote_date END AS quote_date,CASE WHEN q.quote_date || 'T' || q.quote_time >= COALESCE(b.quote_date,b.trade_date) || 'T' || COALESCE(b.quote_time,'00:00:00') THEN COALESCE(q.quote_time,b.quote_time) ELSE b.quote_time END AS quote_time,CASE WHEN q.quote_date || 'T' || q.quote_time >= COALESCE(b.quote_date,b.trade_date) || 'T' || COALESCE(b.quote_time,'00:00:00') THEN COALESCE(q.quote_source,b.quote_source) ELSE b.quote_source END AS quote_source,b.is_st,CASE WHEN q.quote_date || 'T' || q.quote_time >= COALESCE(b.quote_date,b.trade_date) || 'T' || COALESCE(b.quote_time,'00:00:00') THEN COALESCE(q.updated_at,b.quote_updated_at) ELSE b.quote_updated_at END AS quote_updated_at,CASE WHEN q.quote_date || 'T' || q.quote_time >= COALESCE(b.quote_date,b.trade_date) || 'T' || COALESCE(b.quote_time,'00:00:00') THEN COALESCE(q.pct_change,b.quote_pct_change) ELSE b.quote_pct_change END AS quote_pct_change FROM stock_search_base b LEFT JOIN live_quotes q ON q.code=b.code AND q.instrument_type=b.instrument_type;
